Te = 0.1;
num1 = [1];
den1 = [1 1];
numh = [1 0];
denh = [1 2];

[numd1, dend1] = c2dm(num1, den1, Te, 'zoh');
Gdd = tf(numd1, dend1, Te) %[output:05451bfc]

G2 = tf(num1, den1);
Gh = tf(numh, denh);
Gb = series(G2, Gh);
[numd2, dend2] = c2dm(Gb.Numerator{1},Gb.Denominator{1}, Te, 'zoh');
Gbd = tf(numd2, dend2, Te) %[output:14e18e5d]

G01 = Gdd / (1 + Gbd) %[output:96421364]
zplane(G01.Numerator{1},G01.Denominator{1}) %[output:07dd58ea]
%%
[numd3, dend3] = c2dm(numh, denh, Te, 'zoh');
Ghd = tf(numd3, dend3, Te);

G02 = Gdd / (1 + series(Gdd, Ghd))  %[output:58cb22f4]
zplane(G02.Numerator{1},G02.Denominator{1}) %[output:4b1146e4]


